def anchor(file,quote,page,section='',figure=None):
    text=(S/file).read_text()
    assert quote in text,(file,quote)
    start=text.index(quote)
    first=text[:start].count('\n')+1
    return {'tex_file':'source/'+file,'line_range':[first,first+quote.count('\n')],'page':page,'section':section,'figure_or_table':figure,'quoted_text':quote,'anchor_kind':'existing_span','insertion_point':None}
def issue(id,severity,category,loc,problem,reasons,instruction,acceptance,extra=()):
    return {'id':id,'severity':severity,'category':category,'location':loc,'additional_anchors':list(extra),'problem':problem,'reasoning_chain':reasons,'predicted_reviewer_objection':'Simulated reviewer: '+problem,'fix':{'type':'rewrite' if category!='figures' else 'redesign_figure','instruction':instruction,'target_text':None,'required_inputs':['Existing cited source passages and values; no new experiment required'],'acceptance_criteria':acceptance,'estimated_effort':'small','blocks_submission':False},'fix_window':'unknown','depends_on':[]}
